from PIL import Image
im=Image.open('/home/robot/captures/top_002.png').convert('L')
w,h=im.size
px=im.load()
# find dark blobs (bores) in fixture region
import collections
seen=[[False]*w for _ in range(h)]
blobs=[]
for y in range(150,300):
  for x in range(250,450):
    if px[x,y]<60 and not seen[y][x]:
      q=[(x,y)];seen[y][x]=True;pts=[]
      while q:
        a,b=q.pop();pts.append((a,b))
        for dx in(-1,0,1):
          for dy in(-1,0,1):
            nx,ny=a+dx,b+dy
            if 0<=nx<w and 0<=ny<h and not seen[ny][nx] and px[nx,ny]<60:
              seen[ny][nx]=True;q.append((nx,ny))
      if 3<=len(pts)<=400:
        cx=sum(p[0] for p in pts)/len(pts);cy=sum(p[1] for p in pts)/len(pts)
        blobs.append((len(pts),round(cx,1),round(cy,1)))
for b in sorted(blobs,reverse=True)[:15]:print(b)
EOF

